"use client";

const getFirstInitial = (nameOrEmail?: string) => {
    if (!nameOrEmail) return 'C';
    const clean = nameOrEmail.trim();
    if (!clean) return 'C';
    return clean[0].toUpperCase();
};

// Compact "how long ago" label for comment timestamps.
const formatRelativeTime = (ms: number) => {
    if (!ms) return '';
    const diff = Date.now() - ms;
    if (diff < 60_000) return 'just now';
    const mins = Math.floor(diff / 60_000);
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    if (days < 7) return `${days}d ago`;
    return new Date(ms).toLocaleDateString();
};

// Presence liveness. Firestore has no onDisconnect (that's Realtime Database), so a presence
// doc would otherwise survive a tab close forever and every collaborator would look permanently
// online. Each client refreshes its own `updatedAt` on a heartbeat; readers treat a doc whose
// heartbeat is older than PRESENCE_STALE_MS as gone.
const PRESENCE_HEARTBEAT_MS = 25000;
const PRESENCE_STALE_MS = 60000;
const PRESENCE_RECHECK_MS = 15000;

/**
 * Everything on the canvas that owns its own clicks, so a click on it never also
 * means "start a new line here". Shared by the canvas click handler and the
 * press-origin guard beside it — they have to agree on what counts as interactive,
 * and two copies of this list would eventually disagree.
 */
/**
 * Hard ceiling on a single take, for canvas recordings and Demo Studio tracks alike.
 * A recording is uploaded whole to Storage and, for canvas takes, sent whole to the
 * transcription model — both of which are billed by size, and the transcription
 * endpoint's own time budget can't finish a take much longer than this anyway. Ten
 * minutes is far past any voice memo or single-instrument pass, so this catches the
 * left-it-running case rather than interrupting real work.
 */
const MAX_RECORDING_SECONDS = 600;

/**
 * What /api/transcribe can actually finish, expressed as something checkable before
 * the user waits for it.
 *
 * The route has ~40s of budget inside Firebase Hosting's ~60s edge window, and the
 * WHOLE round trip lives in it: downloading the file to the browser, posting those
 * same bytes up to the route, and only then the model. A long or high-bitrate file
 * spends the budget on transport and times out with nothing to show — after a wait
 * long enough that the failure reads as the feature being broken.
 *
 * These are set to comfortably contain what the app itself produces: a 10-minute
 * take at 128 kbps Opus is ~9.6MB, so anything inside these limits is something we
 * made and can handle. Beyond them the answer is known in advance, and saying so
 * immediately is far kinder than a two-minute wait ending in "try again".
 */
const MAX_TRANSCRIBE_SECONDS = MAX_RECORDING_SECONDS;
const MAX_TRANSCRIBE_BYTES = 12 * 1024 * 1024;

/**
 * Encode rate for every take we record, canvas and Demo Studio alike.
 *
 * Opus reaches transparency — the point past which more bits buy nothing anyone can
 * hear — at roughly 96 kbps for stereo music and lower still for a single voice.
 * These takes are one singer or one instrument through a laptop or phone mic, so
 * 128 kbps sits comfortably above that with headroom to spare, and halves what the
 * old 256 kbps wrote to Storage and sent to the transcription model for audio that
 * sounded identical.
 */
const RECORDING_BITS_PER_SECOND = 128000;

/**
 * Words that stand in for other words — pronouns and their compounds, articles,
 * modals — across the three UI languages. No thesaurus carries synonyms for these
 * (there is nothing to substitute a substitute with), so when one turns up empty
 * the panel explains that instead of shrugging "no matches", which read as the
 * feature being broken for some of the most-searched words in a lyric.
 */
const LEXICON_FUNCTION_WORDS = new Set([
    // English
    'anything', 'everything', 'something', 'nothing', 'anyone', 'everyone', 'someone',
    'nobody', 'anybody', 'everybody', 'somebody', 'anywhere', 'everywhere', 'somewhere',
    'nowhere', 'me', 'my', 'mine', 'you', 'your', 'yours', 'we', 'us', 'our', 'ours',
    'they', 'them', 'their', 'theirs', 'he', 'him', 'his', 'she', 'her', 'hers', 'it',
    'its', 'who', 'whom', 'whose', 'this', 'that', 'these', 'those', 'the', 'and', 'but',
    'because', 'was', 'were', 'been', 'being', 'could', 'would', 'should', 'shall', 'might', 'must',
    // Swedish
    'något', 'allt', 'allting', 'ingenting', 'någonting', 'ingen', 'någon', 'alla',
    'jag', 'du', 'han', 'hon', 'den', 'det', 'vi', 'ni', 'de', 'min', 'din', 'sin',
    'vår', 'er', 'deras', 'denna', 'detta', 'dessa', 'och', 'men', 'eftersom',
    'skulle', 'kunde', 'borde',
    // Norwegian
    'noe', 'alt', 'ingenting', 'ingen', 'noen', 'alle', 'jeg', 'dere', 'mi', 'di',
    'vårt', 'denne', 'dette', 'disse', 'og', 'fordi', 'kunne', 'burde',
]);

/**
 * A clicked token reduced to the word itself.
 *
 * Keeps the marks that live INSIDE a word and drops the ones that merely bracket it —
 * the same shape the lyric tokenizer uses (`\p{L}+(?:['’\-]\p{L}+)*`). Stripping every
 * non-letter turned "I've" into "ive": a word the writer never typed, which found no
 * rhymes and was then flagged by the spellchecker as a misspelling of the word it had
 * just been made from.
 */
function cleanClickedWord(raw: string): string {
    return raw
        // One apostrophe, so a curly "I’ve" and a straight "I've" are the same word.
        .replace(/[’ʼ]/g, "'")
        .replace(/[^\p{L}'\-]/gu, '')
        .replace(/^['\-]+|['\-]+$/g, '');
}

/**
 * Keeps the line being typed on screen.
 *
 * Two things push it out of view: the on-screen keyboard, which takes the bottom
 * half of the viewport without the document knowing, and the toolbar docked to
 * the keyboard's top edge. Neither is visible to `scrollIntoView`, which would
 * happily "reveal" a line by parking it underneath both.
 *
 * So the safe band is measured explicitly — visualViewport for the keyboard, a
 * dock allowance for the toolbar — and the page is nudged only when the caret's
 * line has actually left it. That last part is what keeps this quiet: it does
 * nothing on the vast majority of keystrokes, so there is no per-character
 * scrolling and no fight with a smooth animation already in flight.
 *
 * A module-level function rather than a hook: the phrase row is its own
 * component, well outside the page's state.
 */
const DOCK_CLEARANCE_FALLBACK = 104;
const CARET_MARGIN = 20;

function keepEditorInView(el: HTMLElement | null) {
    if (!el || typeof window === 'undefined') return;

    const vv = window.visualViewport;
    const visibleTop = vv ? vv.offsetTop : 0;
    const visibleBottom = vv ? vv.offsetTop + vv.height : window.innerHeight;

    // Measured, not assumed. The docked toolbar is two rows while the keyboard is
    // up — Complete and undo/redo above the tools capsule — which is well over the
    // 104px this used to reserve, so the line being typed was landing underneath
    // it and reading as "nothing happened". Its real height is the only number
    // that keeps working when that bar changes.
    const dock = document.querySelector('[data-canvas-dock]');
    const dockHeight = dock ? dock.getBoundingClientRect().height : DOCK_CLEARANCE_FALLBACK;

    const safeTop = visibleTop + CARET_MARGIN;
    const safeBottom = visibleBottom - dockHeight - CARET_MARGIN;
    // A viewport too short to hold the line and both chrome bars — nothing sane
    // to scroll to, so leave it where it is rather than oscillating.
    if (safeBottom <= safeTop) return;

    const rect = el.getBoundingClientRect();
    let delta = 0;
    if (rect.bottom > safeBottom) delta = rect.bottom - safeBottom;
    else if (rect.top < safeTop) delta = rect.top - safeTop;
    if (delta === 0) return;

    window.scrollBy({ top: delta, behavior: 'smooth' });
}

const CANVAS_INTERACTIVE_SELECTOR =
    '.phrase-row-container, .canvas-add-menu, .canvas-flow-card, .chord-card, .word-token, .suggestions-popover, button, a, input, textarea, select, video, img, [role="button"]';

const getCollabColor = (colorNameOrHex?: string) => {
    if (!colorNameOrHex) return '#A1B5EE';
    if (colorNameOrHex.startsWith('#')) return colorNameOrHex;
    switch (colorNameOrHex.toLowerCase()) {
        case 'green':
        case 'emerald': return '#92CF90';
        case 'pink': return '#F7B3FF';
        case 'purple': return '#E5B5ED';
        case 'blue':
        case 'indigo': return '#A1B5EE';
        case 'rose': return '#F9A8D4';
        case 'amber': return '#FDE047';
        case 'sky': return '#BAE6FD';
        default: return '#A1B5EE';
    }
};

